void ref_scale_q31(
  q31_t * pSrc,
  q31_t scaleFract,
  int8_t shift,
  q31_t * pDst,
  uint32_t blockSize)
{
	uint32_t i;
  int8_t kShift = shift + 1;                     /* Shift to apply after scaling */
  int8_t sign = (kShift & 0x80);
	q63_t temp;

	for(i=0;i<blockSize;i++)
	{
		temp = ((q63_t) pSrc[i] * scaleFract) >> 32;
		if (sign)
			pDst[i] = temp >> -kShift;
		else
			pDst[i] = ref_sat_q31( (q63_t)temp << kShift );
	}
}

