	uint32_t i;
  int8_t kShift = 15 - shift;                      /* Shift to apply after scaling */

	for(i=0;i<blockSize;i++)
	{
		pDst[i] = ref_sat_q15(((q31_t) pSrc[i] * scaleFract) >> kShift);
	}
}

