void ref_cmplx_mag_q31(
  q31_t * pSrc,
  q31_t * pDst,
  uint32_t numSamples)
{
	uint32_t i;
	q31_t acc0,acc1,out;

	for(i=0;i<numSamples*2;i+=2)
	{
		acc0 = (q31_t)(((q63_t)pSrc[i] * pSrc[i]) >> 33);
		acc1 = (q31_t)(((q63_t)pSrc[i+1] * pSrc[i+1]) >> 33);
		out = acc0 + acc1;
		*pDst++ = (q31_t)(sqrtf((float)out / 2147483648.0f) * 2147483648.0f);
	}
}

void ref_cmplx_mag_q15(
