float32_t ref_detrm(float32_t *pSrc, float32_t *temp, uint32_t size)
{
   float32_t s = 1, det = 0;
   int i, j, m, n, c;

   if ( size == 1 )
   {
      return ( pSrc[ 0 ] );
   }
   else
   {
      det = 0;

      for ( c = 0;c < size;c++ )
      {
         m = 0;
         n = 0;

         for ( i = 0;i < size;i++ )
         {
            for ( j = 0;j < size;j++ )
            {
               temp[ i*size + j ] = 0;

               if ( i != 0 && j != c )
               {
                  temp[ m*(size-1) + n ] = pSrc[ i*size + j ];

                  if ( n < ( size - 2 ) )
                  {
                     n++;
                  }
                  else
                  {
                     n = 0;
                     m++;
                  }
               }
            }
         }

         det += s * ( pSrc[ c ] * ref_detrm( temp, temp + size*size, size - 1 ) );
         s = -s;
      }
   }

   return ( det );
}


