{
   int p, q, m, n, i, j;

	 if (size == 1)
	 {
		 pDst[0] = 1;
		 return;
	 }

   for ( q = 0;q < size;q++ )
   {
      for ( p = 0;p < size;p++ )
      {
         m = 0;
         n = 0;

         for ( i = 0;i < size;i++ )
         {
            for ( j = 0;j < size;j++ )
            {
               temp[ i*size + j ] = 0;

               if ( i != q && j != p )
               {
                  temp[ m*(size-1) + n ] = pSrc[ i*size + j ];

                  if ( n < ( size - 2 ) )
									{
										n++;
									}
                  else
                  {
                     n = 0;
                     m++;
                  }
               }
            }
         }

         pDst[ q*size + p ] = ref_pow( -1, q + p ) * ref_detrm( temp, temp + (size-1)*(size-1), size - 1 );
      }
   }
}



