  }
  return (len - i);
}

int _write (int fd, char * ptr, int len) 
{
  int i;

  for (i = 0; i < len; i++) SER_PutChar (*ptr++);
  return (i);
}

caddr_t _sbrk (int incr) 
{
  static char * heap;
         char * prev_heap;

  if (heap == NULL) 
  {
    heap = (char *)&__HeapBase;
  }

  prev_heap = heap;

  if ((heap + incr) > (char *)&__HeapLimit) 
  {
    errno = ENOMEM;
    return (caddr_t) -1;
  }

  heap += incr;

  return (caddr_t) prev_heap;
}

